"""Czech reviewer appendix built from the independently exported audit tables."""
import json
from pathlib import Path

def section(table,n,link):
    r=json.loads((Path(__file__).resolve().parent/'results/reviewer_audit/summary.json').read_text())
    g=r['geometry'];t=r['tropopause']
    u=lambda x,d=2:f'{x:.{d}f}'.replace('.',',')
    body='''<section id="recenzni-audit"><h2>Technický dodatek: audit čtyř předpokladů</h2>
<p>Tento dodatek reaguje na požadavky recenzenta na spektroskopii, osvětlení, tropopauzu a povrchovou bilanci. Kontroluje skutečné soubory a uložené experimenty; navíc přidává nové pásmové přepočty pro čtyři a šestnáct slunečních úhlů. Základní čísla jsou výsledky definovaného schématu. Úplné fyzikální ověření všech požadovaných absorpčních mechanismů zůstává podmíněné níže uvedenými chybějícími údaji.</p>
<h3 id="audit-spektroskopie">1. Databáze, profil čar a párová absorpce</h3>
<p><strong>Pro hlavní globální výpočet nelze uvést „HITRAN2024, Voigt, ořez 25 cm⁻¹“.</strong> Takové označení by směšovalo dva různé výpočty. Hlavní model čte již vytvořené tabulky korelovaného k; vlastní čárový doplněk počítá čáry přímo a má jiné předpoklady.</p>'''
    body+=table(['Kontrolovaná součást','Doložený stav'],[
        ['Hlavní tabulky','rrtmgp-data v1.9; soubory rrtmgp-gas-sw-g224.nc a rrtmgp-gas-lw-g256.nc. Vnitřní historie SW uvádí 16. 11. 2018 a původní rrtmgp-absorption-coefficients-sw_r2070.nc; LW nese také úpravy z roku 2019. Konkrétní soubory jsou jednoznačně určeny SHA256. Verze distribuce není verzí HITRAN.'],
        ['Publikovaný původ této generace RRTMGP','Dokumentace CKDMIP uvádí LBLRTM 12.8, AER line file aer_v_3.6, převážně založený na HITRAN2012, a kontinuum MT_CKD3.2. To dokládá původ modelové větve, nikoli každý parametr dávky, která vytvořila náš konkrétní binární soubor.'],
        ['Tvar čar a ořez hlavních tabulek','Při našem běhu se již nevolí Voigtův profil ani vzdálenost ořezu: tyto volby jsou zapečeny do koeficientů. Původní generátorový vstup TAPE5 pro tyto soubory není přiložen. Přesné přepínače line mixing, korekcí křídel a cutoff proto nejsou ověřené. Samotná znalost LBLRTM neopravňuje označit veškerou jeho CO₂ optiku za čistý Voigt s ostrým ořezem 25 cm⁻¹.'],
        ['Omezený vlastní čárový doplněk','HITRANonline export z 18. 11. 2026, nikoli certifikovaná zmrazená edice HITRAN2024. Voigt, tlakové rozšíření vzduchem a vlastní molekulou, hlavní řez křídel ±25 cm⁻¹, vodní pedestal při 25 cm⁻¹ a vodní kontinuum MT_CKD4.3. Intenzitní práh a citlivosti jsou u každého běhu v jeho config; tento starší doplněk neobsahuje úplnou párovou CIA ani CO₂ line mixing a není hlavním globálním výsledkem.'],
        ['CO₂–N₂ a CO₂–O₂ CIA','Úplné zahrnutí těchto párů není doloženo. Názvy minor absorbers a hustotní škálování N₂/O₂ samy neprokazují CO₂ párovou složku. Rozšíření molekulární čáry srážkami s N₂/O₂ je jiný mechanismus než samostatná párová absorpce.']])
    body+=f'''<p><strong>Přímý test koeficientů.</strong> Při změně pouze CO₂ z 280 na 560 ppm je v pásmu 12 850–16 000 cm⁻¹ maximální absolutní změna absorpční optické tloušťky přes všechny profily, vrstvy a body g rovna <strong>{r['spectroscopy']['CO2_280_to_560_max_abs_delta_tau_band_12850_16000_cm1']:.1e}</strong>. V tomto pásmu tedy schéma na CO₂ nereaguje, přestože zasahuje do rozsahu samostatných dat O₂–CO₂. To vylučuje úplné zachycení tohoto katalogového rozsahu se správnou závislostí na CO₂. Test neurčuje velikost chybějícího toku a nedokazuje nulovou CIA ve všech ostatních pásmech.</p>
<p>Oficiální katalog HITRAN uvádí pro O₂–CO₂ dvě dílčí sady: 9105–9545 cm⁻¹ při 293 K a 12 600–13 839 cm⁻¹ při 296 K, celkově v obálce přibližně 0,723–1,098 µm. Druhá sada překrývá testované modelové pásmo. Neleží tedy přímo v pásmech 1,6 a 2,0 µm. Samostatný soubor CO₂–N₂ není v tomto katalogu uveden. Jeho absence není důkazem nulové fyzikální absorpce. Pro oblast kolem 1,6 µm jsou relevantní také novější data CO₂–H₂O (5700–6300 cm⁻¹), jejichž plné zachycení starými tabulkami rovněž nebylo prokázáno. <a href="https://hitran.org/cia/">Oficiální katalog CIA</a> a <a href="https://hitran.org/data/CIA/CIA_Readme_2024.pdf">dokumentace vydání 2024</a>.</p>
<p>Požadavek recenzenta na úplnou spektroskopickou specifikaci je proto <strong>splněn jen částečně</strong>: vstupní soubory a publikovaný původ jsou určeny, ale přesný generátorový cutoff a úplná požadovaná párová CIA zůstávají otevřené. Doplňovat CIA přímo do přeuspořádaných bodů g bez kontroly překryvu by mohlo zavést dvojí započtení. K uzavření je nutný dohledaný generátorový vstup nebo nový ověřený čárový referenční běh s explicitními páry a testem jejich přírůstku.</p>
<p class="source"><a href="https://confluence.ecmwf.int/spaces/CKDMIP/pages/188045212/How%2BCKD%2Btools%2Bwork#HowCKDtoolswork-RRTMGP">Dokumentace původu RRTMGP od účastníků CKDMIP</a>; <a href="https://doi.org/10.1029/2019MS001621">původní článek RRTMGP</a>; {link('results/reviewer_audit/summary.json','metadata, otisky a číselný test optiky')}.</p>
<h3 id="audit-osvetleni">2. Solární zdroj a přesná úhlová integrace</h3>
<p>Použit je produkt <code>{g['spectrum_file']}</code>, vytvořený 30. 11. 2022: <strong>TSIS-1 HSRS v2 na 1nm síti</strong>, v hlavním souboru 202–2730 nm. Vnější oblasti doplňuje přiložené úplné spektrum LASP. Přesné stažené soubory a otisky jsou v {link('data_sources.json','seznamu vstupů')}. Integrály zdroje přes 14 pásem nahrazují nativní pásmové energie; relativní rozdělení energie mezi body g uvnitř každého pásma zůstává původní. Jde tedy o pásmové převážení TSIS, nikoli nový čárový přenos s plně rozlišeným TSIS spektrem. <a href="https://lasp.colorado.edu/lisird/data/tsis1_hsrs/">Zdroj LASP</a>.</p>
<p>Rozsah SW schématu 820–50 000 cm⁻¹ odpovídá přibližně 0,20–12,20 µm. Vypuštěné okraje úplného solárního spektra představují přibližně 0,559 W/m² kolmo ke slunečním paprskům, asi 0,041 % jeho integrálu; zahrnuté pásmové podíly jsou normalizovány na celkovou intenzitu TSI každého profilu. Sezónní TSI z RFMIP je zachována. Vlastní program neprovádí další násobení 1/4: horizontální projekci a denní průměr řeší úhlová integrace.</p>
<div class="formula">μ₀(H) = sin φ sin δ + cos φ cos δ cos H<br>H₀ = arccos[clip(−tan φ tan δ, −1, 1)]<br>Hₖ = xₖ H₀; Wₖ = wₖ H₀/(2π); ⟨ΔF⟩ = Σᵢ pᵢ Σₖ Wᵢₖ ΔFᵢ(μᵢₖ)</div>
<p>φ je šířka profilu, δ = arcsin[sin(23,44°) sin(2π(d − 79,5)/365,2422)], d je počet dní od 1. 1. 2014 včetně zlomku dne. xₖ a wₖ jsou uzly a váhy 8bodové Gaussovy–Legendreovy kvadratury na [−1,1]; jejich přesné hodnoty pro každý profil jsou v CSV. μ₀ se omezí zdola nulou, v polární noci je příspěvek nulový. Faktor 1/μ₀ působí uvnitř radiačního řešiče na přímou optickou dráhu. Průměrují se vypočtené toky, nikoli optické dráhy ani absorpce vypočtená z průměrného μ₀.</p>
<p><strong>Jediný efektivní úhel se nepoužívá.</strong> Kladná μ₀ v základní kvadratuře sahají od {u(g['mu_min'],6)} do {u(g['mu_max'],6)}. Šířky 100 sloupců sahají od {u(g['latitude_min'],1)}° do {u(g['latitude_max'],1)}°. Integrace přes šířku a roční dobu je reprezentována normalizovanými vahami <code>profile_weight</code> a datem každého profilu, nikoli další nezávislou Gaussovou integrací přes šířku. Výsledný vážený vstup SW na vodorovnou plochu TOA je {u(g['weighted_TOA_incident_Wm2'],3)} W/m². Zůstává to aproximace ročního jasného průměru reprezentativním souborem RFMIP.</p>'''
    bands=r['band_angular_convergence']
    get=lambda nm,b:next(x for x in bands if x['nmu']==nm and x['band_zero_based']==b)
    body+='<p>Následuje nový test 280 → 420 ppm. Hodnoty jsou změny čistého SW toku na povrchu v celém uvedeném modelovém pásmu; úzké absorpční pásmo 1,6 µm není z širokého intervalu uměle vyříznuto.</p>'
    body+=table(['Pásmo / rozsah µm','4 úhly (W/m²)','8 úhlů (W/m²)','16 úhlů (W/m²)','|8 − 16| / |16|'],
        [[label]+[n(get(k,b)['SW_net_surface_Wm2'],6) for k in [4,8,16]]+[u(100*abs(get(8,b)['SW_net_surface_Wm2']-get(16,b)['SW_net_surface_Wm2'])/abs(get(16,b)['SW_net_surface_Wm2']),3)+' %']
        for b,label in [(6,'okolí 1,6 / 1,299–1,626'),(4,'okolí 2,0 / 1,942–2,151')]])
    body+=f'<p>Konvergence úhlů omezuje numerickou chybu této integrace; neověřuje spektrální úplnost ani roční reprezentativnost vstupů. {link("results/reviewer_audit/solar_geometry_nodes.csv","Všech 800 uzlů a jejich vah")} · {link("results/reviewer_audit/band_angular_convergence.csv","Všech 14 pásem pro 4/8/16 úhlů")}.</p>'
    body+=f'''<h3 id="audit-tropopauza">3. Přesné hranice stratosférického průměru</h3>
<p>Hodnota −1,348 → −1,100 K pro 280 → 420 ppm <strong>nepoužívá jedinou pevnou tropopauzu v hPa</strong>. Dolní hranicí je rozhraní j = tᵢ diagnostikované v každém profilu podle algoritmu v metodice. Jeho tlaky sahají od {u(t['min_hPa'],3)} do {u(t['max_hPa'],3)} hPa a hypsometrické výšky od {u(t['min_km'],3)} do {u(t['max_km'],3)} km nad modelovým povrchem. Vážené průměry jsou {u(t['weighted_hPa'],3)} hPa a {u(t['weighted_km'],3)} km; tyto průměry slouží jen k popisu a nejsou náhradní integrační hranicí. Jde o diskrétní tepelnou diagnózu na hrubé síti, nikoli o nezávisle pozorované tropopauzy.</p>
<div class="formula">⟨ΔT⟩ = ΣᵢΣⱼ pᵢ Δpᵢⱼ Mᵢⱼ ΔTᵢⱼ / ΣᵢΣⱼ pᵢ Δpᵢⱼ Mᵢⱼ<br>Mᵢⱼ = 1 pro j &lt; tᵢ a tlak středu vrstvy ≥ 100 Pa; jinak 0</div>
<p>Váhy pᵢ jsou normalizované váhy RFMIP, Δp je rozdíl tlaku dolního a horního rozhraní. Faktor 1/g pro převod na hmotnost se v poměru vykrátí. Svislé indexy rostou od vrcholu k povrchu. Základní horní mez „1 hPa“ vybírá celé vrstvy podle jejich středu; první skutečně zahrnuté horní rozhraní leží u všech sloupců na {u(t['actual_top_interface_hPa_min'],6)} hPa. Proto je hlavní číslo přesně průměrem těchto celých modelových vrstev, nikoli integrálem ostře oříznutým při 100 Pa. Alternativa v posledním řádku ořízne tlakovou hmotnost protínající vrstvy přesně na 100 Pa při konstantním ΔT uvnitř vrstvy.</p>'''
    labels={('averaging_boundary_only','one_level_higher'):'Pouze průměrování, hranice o vrstvu výše',('averaging_boundary_only','baseline'):'Základní průměr i FDH',('averaging_boundary_only','one_level_lower'):'Pouze průměrování, hranice o vrstvu níže',('FDH_recomputed','one_level_higher'):'Nová FDH, hranice o vrstvu výše',('FDH_recomputed','one_level_lower'):'Nová FDH, hranice o vrstvu níže',('exact_upper_boundary','baseline'):'Přesný horní řez na 100 Pa'}
    body+=table(['Test, 280 → 420 ppm','Bez SW CO₂ (K)','S SW CO₂ (K)','Rozdíl (K)','Zmírnění ochlazení'],
        [[labels[(x['test'],x['boundary'])],n(x['no_CO2_SW_K'],4),n(x['full_K'],4),n(x['SW_offset_K'],4),u(x['cooling_reduction_percent'],2)+' %'] for x in r['temperature']])
    body+=f'''<p>Posun spodní hranice směrem níže při pouhém průměrování přidává vrstvy s nulovou teplotní změnou, protože původní FDH ponechala troposféru pevnou. Oba průměry se proto stejně zředí a jejich procentní poměr se zde nezmění. Naproti tomu skutečné přepočty FDH mění řešenou oblast a dávají 16,01–20,64 %, tedy asi −2,37 až +2,27 procentního bodu proti základu. To podporuje recenzentovu výhradu, ale není to statistický interval nejistoty. Samotný přesný horní řez mění podíl jen o přibližně +0,017 procentního bodu.</p>
<p>{link('results/reviewer_audit/tropopause_by_profile.csv','Přesný index, tlak a výška hranic všech 100 profilů')} · {link('results/reviewer_audit/temperature_boundary_sensitivity.csv','Nezaokrouhlené průměry a tlakové hmotnosti')}. Jednotka K u změny teploty má stejnou číselnou velikost jako změna v °C.</p>
<h3 id="audit-povrch">4. SW a LW na povrchu a u spodní atmosféry</h3>
<p>Všechny další tabulky používají stejné profily a koncentrace jako hlavní výpočet. ΔL↓ je změna dopadajícího LW záření; ΔLW<sub>net</sub> = ΔL↓ − ΔL↑ je změna čistého toku. Na povrchu s pevnou teplotou a emisivitou ε = {u(r['surface_emissivity'],2)} platí ΔL↑ = (1 − ε)ΔL↓, tedy ΔLW<sub>net</sub> = εΔL↓. Emise povrchu zůstává pevná, odražená část přicházejícího LW se mění. Maximální odchylka této identity v jednotlivých sloupcích a všech zdejších experimentech je {r['verification']['max_surface_LW_net_minus_emissivity_times_LW_down_Wm2']:.2e} W/m², v mezích numerického zaokrouhlení.</p>
<p><strong>Okamžitý účinek celého růstu CO₂ při pevné teplotě.</strong> Poslední poměr porovnává úbytek SW absorbovaného povrchem s přírůstkem čistého LW na témže rozhraní. Všechny toky jsou ve W/m²; procenta jsou poměrem vážených průměrů.</p>'''
    flux=r['flux'];select=lambda experiment,h:[x for x in flux if x['experiment']==experiment and x['reference_height_m']==h]
    body+=table(['ppm','ΔS↓','ΔSW net','ΔL↓','ΔLW net','Δ(SW + LW) net','|ΔSW net| / ΔLW net'],
        [[f'280 → {x["c1"]}']+[n(x[k],4) for k in ['sw_flux_down_Wm2','SW_net_Wm2','lw_flux_down_Wm2','LW_net_Wm2','total_net_Wm2']]+[u(x['SW_net_loss_over_LW_net_gain_percent'],2)+' %'] for x in select('instant_full',0)])
    body+='''<p>Pro 280 → 420 ppm tedy dopadající SW ubude o 0,2000 W/m² a dopadající LW přibude o 1,1056 W/m²: poměr těchto dopadajících toků je 18,09 %. Pro bilanci absorbované energie je odpovídající poměr 15,77 %. Míchání čistého SW s dopadajícím LW by dalo třetí, fyzikálně odlišně definovaný poměr. Kladný součet v tabulce je radiační příkon při fixovaných teplotách, nikoli nová rovnováha ani předpověď přízemní teploty.</p>
<p><strong>Po stratosférické adaptaci.</strong> První tři řádky zahrnují celý růst CO₂. Zbývající tři jsou dvojitý rozdíl B − C, tedy pouze příspěvek přisuzovaný jeho SW absorpci a jí vyvolané LW odezvě. Tyto dva významy přírůstku LW se nesměšují.</p>'''
    body+=table(['Experiment / ppm','ΔSW net (W/m²)','ΔL↓ (W/m²)','ΔLW net (W/m²)','Δ(SW + LW) net (W/m²)'],
        [[f'{label}, 280 → {x["c1"]}']+[n(x[k],5) for k in ['SW_net_Wm2','lw_flux_down_Wm2','LW_net_Wm2','total_net_Wm2']]
        for exp,label in [('FDH_full','Celý CO₂ po FDH'),('SW_induced_B_minus_C','Pouze SW příspěvek B − C')] for x in select(exp,0)])
    body+='''<p><strong>Skutečnou horní hranici mezní vrstvy tento soubor neurčuje.</strong> RFMIP zde neobsahuje diagnostikovanou výšku mezní vrstvy, větrný profil ani turbulentní toky. Tropopauza je jiná hranice a nelze ji za horní okraj mezní vrstvy dosadit. Pro kontrolovatelné srovnání proto uvádíme pevné referenční výšky 0,5, 1 a 2 km nad modelovým povrchem. Ty nejsou označeny za skutečnou hloubku mezní vrstvy. Toky jsou v každém sloupci lineárně interpolovány mezi hypsometrickými výškami rozhraní původního profilu a potom váženy; nejde o další nezávisle rozlišené modelové vrstvy.</p>
<p>Následující kontrola používá okamžitý experiment. Záporný ΔSW net ve výšce vyjadřuje změnu energie pro celý sloupec pod tímto rozhraním, nikoli samotnou absorpci mezní vrstvy. Absorpci mezi dvěma hranicemi je nutné určit rozdílem jejich čistých toků.</p>'''
    body+=table(['Referenční výška / ppm','ΔSW net (W/m²)','ΔL↓ (W/m²)','ΔLW net (W/m²)','Δ(SW + LW) net (W/m²)','|ΔSW net| / ΔLW net'],
        [[f'{u(h/1000,1)} km / 280 → {x["c1"]}']+[n(x[k],4) for k in ['SW_net_Wm2','lw_flux_down_Wm2','LW_net_Wm2','total_net_Wm2']]+[u(x['SW_net_loss_over_LW_net_gain_percent'],2)+' %']
        for h in [500,1000,2000] for x in select('instant_full',h)])
    body+=f'''<p>{link('results/reviewer_audit/flux_decomposition.csv','Úplný rozklad SW/LW ve všech výškách, koncentracích a experimentech')} obsahuje také změny toků nahoru a oba přesně definované poměry. {link('results/reviewer_audit/flux_decomposition_by_profile.csv','Totéž pro každý jednotlivý profil')} umožňuje zkontrolovat vážení. Požadavek na povrchovou tabulku je splněn; číselný výsledek na skutečném vrcholu mezní vrstvy vyžaduje její fyzikální diagnózu nebo příslušná vstupní data.</p>
<div class="note"><strong>Stav auditu:</strong> geometrie, úhlová citlivost, přesná definice stratosférického průměru a povrchový rozklad jsou doloženy. Přesný generátorový cutoff, úplná CO₂ párová CIA a skutečná výška mezní vrstvy nejsou uzavřeny. Proto výsledky zůstávají podmíněným fyzikálním srovnáním v popsaném modelu, nikoli úplně ověřenou referencí požadovanou recenzentem.</div>
<p class="small">Reprodukce dodatku: {link('reviewer_audit.py','výpočty a exporty')} · {link('reviewer_section.py','sestavení technického textu')} · {link('audit_evidence/reviewer_sources.json','primární zdroje a rozsah jejich použití')}.</p></section>'''
    return body
